import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Unified Plugin Crate Naming","description":"","frontmatter":{"title":"Unified Plugin Crate Naming","type":"adr","date":"2026-08-29T00:00:00.000Z","status":"accepted","status_note":"Accepted"},"headers":[],"relativePath":"handl/project/adrs/archived/0033-unified-plugin-crate-naming.md","filePath":"vendored/handl/project/adrs/archived/0033-unified-plugin-crate-naming.md"}`),a={name:`handl/project/adrs/archived/0033-unified-plugin-crate-naming.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0033-unified-plugin-crate-naming" tabindex="-1">ADR-0033: Unified Plugin Crate Naming <a class="header-anchor" href="#adr-0033-unified-plugin-crate-naming" aria-label="Permalink to “ADR-0033: Unified Plugin Crate Naming”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The Handl platform has 79 <code>plugin-*</code> directories under <code>crates/</code>. Their names have grown organically and are now inconsistent, which makes the workspace hard to navigate, sort, and keep in <code>Cargo.toml</code>. Only <code>plugin-comments</code> and <code>plugin-doc-comments</code> were listed in the root <code>[workspace] members</code> at the time of writing; the rest were only in <code>[workspace.dependencies]</code> or missing entirely.</p><p>Current naming patterns:</p><table tabindex="0"><thead><tr><th>pattern</th><th>count</th></tr></thead><tbody><tr><td><code>plugin-ast-*</code></td><td>13</td></tr><tr><td><code>plugin-grammar-*</code></td><td>10</td></tr><tr><td><code>plugin-token-*</code></td><td>10</td></tr><tr><td><code>plugin-primary-*</code></td><td>9</td></tr><tr><td><code>plugin-infix-*</code></td><td>5</td></tr><tr><td><code>plugin-stmt-*</code></td><td>5</td></tr><tr><td><code>plugin-postfix-*</code></td><td>4</td></tr><tr><td><code>plugin-fmt-*</code></td><td>3</td></tr><tr><td><code>plugin-lsp-*</code></td><td>3</td></tr><tr><td><code>plugin-diag-*</code></td><td>1</td></tr><tr><td><code>plugin-typecheck-*</code></td><td>1</td></tr><tr><td><code>plugin-vm-*</code></td><td>1</td></tr><tr><td>bare <code>plugin-&lt;name&gt;</code></td><td>14</td></tr></tbody></table><p>Notable inconsistencies:</p><ul><li>Token plugins are split between bare crates (<code>plugin-booleans</code>, <code>plugin-numbers</code>, <code>plugin-strings</code>, <code>plugin-null</code>, <code>plugin-bytes</code>, <code>plugin-identifiers</code>, <code>plugin-keywords</code>, <code>plugin-operators</code>, <code>plugin-delimiters</code>) and <code>plugin-token-*</code> crates (<code>plugin-token-bool</code>, <code>plugin-token-number</code>, <code>plugin-token-comment</code>, etc.).</li><li>Near-duplicates exist, e.g. <code>plugin-comment-tokens</code> vs <code>plugin-token-comment</code>.</li><li>Plural and singular forms are mixed, e.g. <code>plugin-primary-arrays</code> vs. <code>plugin-ast-array</code>.</li><li>Parser-shape namespaces overlap: <code>plugin-primary-*</code>, <code>plugin-postfix-*</code>, <code>plugin-infix-*</code>, and <code>plugin-stmt-*</code> all live at the top level.</li><li>Backend/target plugins use mixed conventions, e.g. <code>plugin-vm-rust</code> and <code>native-plugin-example</code> (whose package name is <code>native-plugin-example</code>).</li></ul><p>A single naming convention is needed before the workspace manifests and kit registries can be maintained automatically.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Every plugin crate will use the directory name</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>plugin-&lt;domain&gt;-&lt;construct&gt;</span></span></code></pre></div><p>and the Cargo package name</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>handl-plugin-&lt;domain&gt;-&lt;construct&gt;</span></span></code></pre></div><p>Approved domains:</p><table tabindex="0"><thead><tr><th>domain</th><th>meaning</th></tr></thead><tbody><tr><td><code>token</code></td><td>lexer token kinds</td></tr><tr><td><code>grammar</code></td><td>grammar rules and parser shapes</td></tr><tr><td><code>ast</code></td><td>AST node shapes</td></tr><tr><td><code>fmt</code></td><td>formatter behaviors</td></tr><tr><td><code>diag</code></td><td>diagnostics</td></tr><tr><td><code>lsp</code></td><td>LSP features</td></tr><tr><td><code>typecheck</code></td><td>type checker rules and behaviors</td></tr><tr><td><code>target</code></td><td>codegen / VM / backend plugins</td></tr></tbody></table><p>Rules:</p><ol><li>Construct names are <strong>singular</strong>: <code>bool</code>, <code>number</code>, <code>string</code>, <code>identifier</code>, <code>operator</code>, <code>delimiter</code>, <code>keyword</code>, <code>comment</code>, <code>call</code>, <code>array</code>, <code>object</code>, <code>stmt</code>, <code>let</code>, <code>const</code>, <code>import</code>, <code>export</code>, <code>module</code>, <code>index</code>, <code>field</code>, <code>pipe</code>, <code>assign</code>, etc.</li><li>Bare token/keyword/operator/identifier/boolean/number/string/comment/ bytes/null crates collapse into <code>plugin-token-*</code>.</li><li>Parser-shape crates (<code>primary</code>, <code>postfix</code>, <code>infix</code>, <code>stmt</code>) move under <code>plugin-grammar-*</code> with the form <code>plugin-grammar-&lt;shape&gt;-&lt;construct&gt;</code>.</li><li>Plurals become singular, e.g. <code>plugin-primary-arrays</code> becomes <code>plugin-grammar-primary-array</code>.</li><li>Near-duplicates are merged or removed; the canonical token remains <code>plugin-token-comment</code>.</li><li>Backends use the <code>target</code> domain: <ul><li><code>plugin-vm-rust</code> -&gt; <code>plugin-target-rust</code></li><li><code>plugin-native-example</code> -&gt; <code>plugin-target-native-example</code></li></ul></li><li>Once a crate follows the naming scheme it is added to both the root <code>[workspace] members</code> and, when used by other crates, <code>[workspace.dependencies]</code>.</li></ol><h3 id="example-mappings" tabindex="-1">Example mappings <a class="header-anchor" href="#example-mappings" aria-label="Permalink to “Example mappings”">​</a></h3><table tabindex="0"><thead><tr><th>current directory</th><th>proposed directory</th><th>current package</th><th>proposed package</th></tr></thead><tbody><tr><td><code>plugin-booleans</code></td><td><code>plugin-token-bool</code></td><td><code>handl-plugin-booleans</code></td><td><code>handl-plugin-token-bool</code></td></tr><tr><td><code>plugin-numbers</code></td><td><code>plugin-token-number</code></td><td><code>handl-plugin-numbers</code></td><td><code>handl-plugin-token-number</code></td></tr><tr><td><code>plugin-strings</code></td><td><code>plugin-token-string</code></td><td><code>handl-plugin-strings</code></td><td><code>handl-plugin-token-string</code></td></tr><tr><td><code>plugin-bytes</code></td><td><code>plugin-token-bytes</code></td><td><code>handl-plugin-bytes</code></td><td><code>handl-plugin-token-bytes</code></td></tr><tr><td><code>plugin-null</code></td><td><code>plugin-token-null</code></td><td><code>handl-plugin-null</code></td><td><code>handl-plugin-token-null</code></td></tr><tr><td><code>plugin-identifiers</code></td><td><code>plugin-token-identifier</code></td><td><code>handl-plugin-identifiers</code></td><td><code>handl-plugin-token-identifier</code></td></tr><tr><td><code>plugin-keywords</code></td><td><code>plugin-token-keyword</code></td><td><code>handl-plugin-keywords</code></td><td><code>handl-plugin-token-keyword</code></td></tr><tr><td><code>plugin-operators</code></td><td><code>plugin-token-operator</code></td><td><code>handl-plugin-operators</code></td><td><code>handl-plugin-token-operator</code></td></tr><tr><td><code>plugin-delimiters</code></td><td><code>plugin-token-delimiter</code></td><td><code>handl-plugin-delimiters</code></td><td><code>handl-plugin-token-delimiter</code></td></tr><tr><td><code>plugin-comment-tokens</code></td><td><code>plugin-token-comment</code></td><td><code>handl-plugin-comment-tokens</code></td><td><code>handl-plugin-token-comment</code></td></tr><tr><td><code>plugin-primary-arrays</code></td><td><code>plugin-grammar-primary-array</code></td><td><code>handl-plugin-primary-arrays</code></td><td><code>handl-plugin-grammar-primary-array</code></td></tr><tr><td><code>plugin-primary-identifiers</code></td><td><code>plugin-grammar-primary-identifier</code></td><td><code>handl-plugin-primary-identifiers</code></td><td><code>handl-plugin-grammar-primary-identifier</code></td></tr><tr><td><code>plugin-primary-objects</code></td><td><code>plugin-grammar-primary-object</code></td><td><code>handl-plugin-primary-objects</code></td><td><code>handl-plugin-grammar-primary-object</code></td></tr><tr><td><code>plugin-primary-values</code></td><td><code>plugin-grammar-primary-value</code></td><td><code>handl-plugin-primary-values</code></td><td><code>handl-plugin-grammar-primary-value</code></td></tr><tr><td><code>plugin-postfix-calls</code></td><td><code>plugin-grammar-postfix-call</code></td><td><code>handl-plugin-postfix-calls</code></td><td><code>handl-plugin-grammar-postfix-call</code></td></tr><tr><td><code>plugin-postfix-index</code></td><td><code>plugin-grammar-postfix-index</code></td><td><code>handl-plugin-postfix-index</code></td><td><code>handl-plugin-grammar-postfix-index</code></td></tr><tr><td><code>plugin-postfix-field</code></td><td><code>plugin-grammar-postfix-field</code></td><td><code>handl-plugin-postfix-field</code></td><td><code>handl-plugin-grammar-postfix-field</code></td></tr><tr><td><code>plugin-infix-pipe</code></td><td><code>plugin-grammar-infix-pipe</code></td><td><code>handl-plugin-infix-pipe</code></td><td><code>handl-plugin-grammar-infix-pipe</code></td></tr><tr><td><code>plugin-infix-assign</code></td><td><code>plugin-grammar-infix-assign</code></td><td><code>handl-plugin-infix-assign</code></td><td><code>handl-plugin-grammar-infix-assign</code></td></tr><tr><td><code>plugin-stmt-let</code></td><td><code>plugin-grammar-stmt-let</code></td><td><code>handl-plugin-stmt-let</code></td><td><code>handl-plugin-grammar-stmt-let</code></td></tr><tr><td><code>plugin-stmt-const</code></td><td><code>plugin-grammar-stmt-const</code></td><td><code>handl-plugin-stmt-const</code></td><td><code>handl-plugin-grammar-stmt-const</code></td></tr><tr><td><code>plugin-stmt-import</code></td><td><code>plugin-grammar-stmt-import</code></td><td><code>handl-plugin-stmt-import</code></td><td><code>handl-plugin-grammar-stmt-import</code></td></tr><tr><td><code>plugin-fmt-statements</code></td><td><code>plugin-fmt-stmt</code></td><td><code>handl-plugin-fmt-statements</code></td><td><code>handl-plugin-fmt-stmt</code></td></tr><tr><td><code>plugin-vm-rust</code></td><td><code>plugin-target-rust</code></td><td><code>handl-plugin-vm-rust</code></td><td><code>handl-plugin-target-rust</code></td></tr><tr><td><code>plugin-native-example</code></td><td><code>plugin-target-native-example</code></td><td><code>native-plugin-example</code></td><td><code>handl-plugin-target-native-example</code></td></tr></tbody></table><p>Crates that already follow the convention, such as <code>plugin-ast-call</code>, <code>plugin-grammar-call</code>, <code>plugin-token-number</code>, <code>plugin-fmt-expression</code>, <code>plugin-diag-expression</code>, <code>plugin-lsp-completion</code>, and <code>plugin-typecheck-core</code>, keep their current form.</p><p>The overlapping comment/doc-comment plugins (<code>plugin-comments</code>, <code>plugin-doc-comments</code>, <code>plugin-token-comment</code>, <code>plugin-comment-tokens</code>) were disambiguated: the canonical comment token piece lives in <code>plugin-token-comment</code>, and the no-op <code>plugin-comments</code> and <code>plugin-doc-comments</code> crates were removed.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to “Positive”">​</a></h3><ul><li><code>[workspace] members</code> can be enumerated mechanically from <code>crates/plugin-*</code>.</li><li>Plugins sort cleanly by domain, making it easy to find all token, grammar, fmt, or target crates.</li><li>Kit manifests and tooling can assume a uniform naming scheme.</li><li>Duplicate and overlapping crates become obvious and can be merged.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to “Negative”">​</a></h3><ul><li>Requires a bulk rename of many directories and package names.</li><li>Every <code>Cargo.toml</code> dependency, kit manifest, and documentation reference must be updated.</li><li>Short-term churn while the workspace is in transition.</li></ul><h2 id="migration-plan" tabindex="-1">Migration plan <a class="header-anchor" href="#migration-plan" aria-label="Permalink to “Migration plan”">​</a></h2><ol><li>Produce a script or codemod that renames directories and updates <code>package.name</code> in each <code>Cargo.toml</code>.</li><li>Update the root <code>Cargo.toml</code> to add every <code>crates/plugin-*</code> directory to <code>[workspace] members</code>.</li><li>Reconcile <code>[workspace.dependencies]</code> so each plugin is declared once under its canonical <code>handl-plugin-&lt;domain&gt;-&lt;construct&gt;</code> name.</li><li>Resolve near-duplicates explicitly (delete or merge).</li><li>Update <code>kit-canonical</code> and any other kit manifests that list plugin ids.</li><li>Update <code>docs/</code>, <code>README</code>, and other references.</li><li>Validate the workspace with <code>cargo check</code> in CI.</li></ol><h2 id="implementation-status" tabindex="-1">Implementation status <a class="header-anchor" href="#implementation-status" aria-label="Permalink to “Implementation status”">​</a></h2><p>Implemented. The bulk rename in <code>crates/</code> and the root <code>Cargo.toml</code> was completed. The overlapping <code>plugin-comments</code> and <code>plugin-doc-comments</code> crates were removed; the canonical comment token remains <code>plugin-token-comment</code>, and no remaining grammar/AST/fmt/diag rules needed to be moved.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><ul><li><strong>Leave current names and only add missing members</strong>: rejected because the existing inconsistencies continue to make discovery and automation difficult.</li><li><strong>Drop the <code>plugin-</code> prefix from package names</strong>, e.g. <code>handl-token-number</code>: rejected because it removes the explicit plugin identity and collides with base crates like <code>handl-ast</code> and <code>handl-lexer</code>.</li><li><strong>Use more top-level domains such as <code>primary</code>, <code>postfix</code>, <code>infix</code>, and <code>stmt</code></strong>: rejected because these are grammar shapes, not primary domains, and would proliferate namespaces.</li><li><strong>Keep <code>plugin-vm-*</code> for backends</strong>: rejected because <code>target</code> is the architectural term already used for target plugins and keeps codegen distinct from the VM core.</li></ul><h2 id="related-work" tabindex="-1">Related work <a class="header-anchor" href="#related-work" aria-label="Permalink to “Related work”">​</a></h2><ul><li>ADR-0001: Generic Node, Trait-Based Capabilities, and Plugin-Driven Canonical Kit</li><li>ADR-0002: Single <code>Plugin</code> Model for Host, Operations, Libraries, Targets, and Options</li><li><code>docs/explanations/design-principles.md</code></li><li><code>kit-canonical</code> crate manifest</li></ul>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};